import os
from functools import wraps
from flask import Flask, send_file, abort

app = Flask(__name__)

# Dossier contenant les images
IMAGES_FOLDER = 'images'

# Décorateur de sécurité pour empêcher l'accès aux fichiers en dehors du dossier images
def secure_image_access(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        name = kwargs.get('name')
        if not name:
            abort(400, "Le paramètre 'name' est requis.")

        # Construire le chemin complet du fichier
        file_path = os.path.join(IMAGES_FOLDER, name)

        # Vérifier que le chemin est dans le dossier images
        if not os.path.abspath(file_path).startswith(os.path.abspath(IMAGES_FOLDER)):
            abort(403, "Accès interdit aux fichiers en dehors du dossier images.")

        # Vérifier que le fichier existe
        if not os.path.isfile(file_path):
            abort(404, "Image non trouvée.")

        return f(*args, **kwargs)
    return decorated_function

# Route pour servir les images
@app.route('/img/<name>')
@secure_image_access
def img(name):
    file_path = os.path.join(IMAGES_FOLDER, name)
    return send_file(file_path)

