from functools import wraps
from http import HTTPStatus
from pathlib import Path
from typing import Callable, Optional

def img(route: str = "/img") -> Callable:
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, **kwargs):
            # URL'den 'ad' parametresini al
            ad = kwargs.get('ad')
            if not ad:
                return "Ad parametresi eksik", HTTPStatus.BAD_REQUEST

            # Dosya yolu oluştur
            file_path = Path(f"görseller/{ad}")

            if not file_path.exists():
                return "Dosya bulunamadı", HTTPStatus.NOT_FOUND

            # Dosya türüne göre Content-Type belirle
            content_type = "image/jpeg"  # Varsayılan
            if file_path.suffix.lower() == ".png":
                content_type = "image/png"
            elif file_path.suffix.lower() == ".gif":
                content_type = "image/gif"
            elif file_path.suffix.lower() == ".webp":
                content_type = "image/webp"

            # Dosyayı aç ve yanıt olarak döndür
            with open(file_path, "rb") as f:
                return f.read(), HTTPStatus.OK, {"Content-Type": content_type}

        # URL rotasını fonksiyona ekleyerek işlevi bağla
        wrapper.__route__ = route
        return wrapper
    return decorator
